// make-photos.mjs — turn tee.png into 4 product photos with Modelfy.
//
// Usage:
//   node --env-file=.env make-photos.mjs
//
// Reads MODELFY_API_KEY from the environment. Prints the link of each
// finished photo (and the session's web page) on stdout.

import { readFile, stat } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const MCP_URL = "https://months-mono-prison-gay.trycloudflare.com/mcp";
const PRODUCT_IMAGE = join(dirname(fileURLToPath(import.meta.url)), "tee.png");
const PRODUCT_NAME = "Linen T-shirt";
const PHOTO_COUNT = 4;
const SETTINGS = {
  mode: "studio",
  background_color: "light grey",
  aspect_ratio: "4:5",
  photos_per_product: PHOTO_COUNT,
  locale: "en",
};

const API_KEY = process.env.MODELFY_API_KEY;
if (!API_KEY) {
  console.error("MODELFY_API_KEY is not set. Run: node --env-file=.env make-photos.mjs");
  process.exit(1);
}

// ---- Minimal MCP client over Streamable HTTP -------------------------------

let sessionId = null;
let nextId = 1;

// The server answers either JSON or a single SSE "data:" event.
async function rpc(method, params, { notification = false } = {}) {
  const headers = {
    Authorization: `Bearer ${API_KEY}`,
    "Content-Type": "application/json",
    Accept: "application/json, text/event-stream",
    "MCP-Protocol-Version": "2025-06-18",
  };
  if (sessionId) headers["Mcp-Session-Id"] = sessionId;

  const body = { jsonrpc: "2.0", method, params };
  if (!notification) body.id = nextId++;

  const res = await fetch(MCP_URL, { method: "POST", headers, body: JSON.stringify(body) });
  sessionId ??= res.headers.get("mcp-session-id");
  if (notification) return null;

  const text = await res.text();
  if (!res.ok) throw new Error(`HTTP ${res.status} from Modelfy: ${text.slice(0, 300)}`);
  const json = text.trimStart().startsWith("{")
    ? JSON.parse(text)
    : JSON.parse(text.split("\n").find((l) => l.startsWith("data:")).slice(5));
  if (json.error) throw new Error(`MCP error ${json.error.code}: ${json.error.message}`);
  return json.result;
}

// Calls a tool and returns its structured result. Throws on tool errors,
// using the server's error code and next_step.
async function callTool(name, args = {}) {
  const result = await rpc("tools/call", { name, arguments: args });
  if (result.isError) {
    const text = result.content?.map((c) => c.text).join(" ") ?? "";
    const err = result.structuredContent?.error ?? null;
    if (err) {
      throw new Error(`${name} failed: ${err.code}: ${err.message} Next: ${err.next_step ?? "-"}`);
    }
    throw new Error(`${name} failed: ${text}`);
  }
  return result.structuredContent ?? {};
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// ---- Steps -----------------------------------------------------------------

async function main() {
  await rpc("initialize", {
    protocolVersion: "2025-06-18",
    capabilities: {},
    clientInfo: { name: "make-photos", version: "1.0.0" },
  });
  await rpc("notifications/initialized", {}, { notification: true });

  const account = await callTool("get_account");
  console.log(
    `Account: ${account.keyKind} key, ${account.credits} credits` +
      (account.sandbox ? " (SANDBOX: photos are samples, nothing is spent)" : ""),
  );

  // 1. Upload the product photo from code (presigned PUT).
  const bytes = (await stat(PRODUCT_IMAGE)).size;
  const session = await callTool("create_upload_session", {
    files: [{ content_type: "image/png", bytes }],
  });
  const upload = session.uploads[0];
  const put = await fetch(upload.put_url, {
    method: "PUT",
    headers: upload.headers,
    body: await readFile(PRODUCT_IMAGE),
  });
  if (!put.ok) throw new Error(`Upload of tee.png failed: HTTP ${put.status}`);

  // Wait until Modelfy has accepted the file.
  let uploaded;
  for (let i = 0; i < 30; i++) {
    uploaded = await callTool("get_uploaded_photos", { session_id: session.session_id });
    if (uploaded.rejected?.length) {
      throw new Error(`Modelfy rejected tee.png: ${JSON.stringify(uploaded.rejected)}`);
    }
    if (uploaded.pending === 0) break;
    await sleep(1000);
  }
  const uploadId = uploaded.ready_upload_ids?.[0];
  if (!uploadId) throw new Error("tee.png did not become ready in time");

  // 2. Plan the session: the exact price, nothing spent yet.
  const plan = await callTool("plan_photos", {
    products: [{ upload_ids: [uploadId], name: PRODUCT_NAME }],
    ...SETTINGS,
  });
  console.log(
    `Plan: ${plan.photos} photos for ${plan.credits} credits (balance ${plan.balance})`,
  );
  if (!plan.enough_credits) throw new Error("Not enough credits for this session");

  // 3. Launch the planned session (the quote makes this safe to retry).
  const launch = await callTool("generate_photos", { quote_id: plan.quote_id });
  const sid = launch.session_id;
  console.log(`Session started: ${sid}`);

  // 4. Wait until every photo is finished.
  let status;
  for (let i = 0; i < 60; i++) {
    status = await callTool("get_photo_session", { session_id: sid, wait_seconds: 45 });
    if (status.status !== "running") break;
  }
  if (!status || status.status === "running") {
    throw new Error(`Session ${sid} is still running. Check it later with get_photo_session.`);
  }

  // 5. Print the links.
  console.log(`\nStatus: ${status.status}`);
  const photos = status.photos ?? [];
  for (const p of photos) {
    console.log(p.url ?? `(no link: ${JSON.stringify(p)})`);
  }
  if (status.web_url) console.log(`All photos: ${status.web_url}`);
  if (photos.length < PHOTO_COUNT) {
    console.warn(`Only ${photos.length} of ${PHOTO_COUNT} photos are ready (see status above).`);
    process.exitCode = 1;
  }
}

main().catch((err) => {
  console.error(err.message);
  process.exit(1);
});

