// make-photos.mjs — turns tee.png into 4 product photos with Modelfy and prints the links.
//
// Usage:  node --env-file=.env make-photos.mjs
// Needs:  MODELFY_API_KEY in the environment (Node 22, no dependencies).

import { readFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const MCP_URL = 'https://months-mono-prison-gay.trycloudflare.com/mcp';
const PRODUCT_IMAGE = join(dirname(fileURLToPath(import.meta.url)), 'tee.png');
const PRODUCT_NAME = 'Linen T-shirt';
const PHOTOS = 4;
const ASPECT_RATIO = '4:5';
const BACKGROUND = 'light grey';

const apiKey = process.env.MODELFY_API_KEY;
if (!apiKey) {
  console.error('MODELFY_API_KEY is not set. Put it in .env and run: node --env-file=.env make-photos.mjs');
  process.exit(1);
}

let rpcId = 0;
let sessionId; // MCP session id, if the server issues one

// One JSON-RPC call over Streamable HTTP. The server may answer with JSON or SSE.
async function rpc(method, params) {
  const res = await fetch(MCP_URL, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${apiKey}`,
      'Content-Type': 'application/json',
      Accept: 'application/json, text/event-stream',
      ...(sessionId ? { 'Mcp-Session-Id': sessionId } : {}),
    },
    body: JSON.stringify({ jsonrpc: '2.0', id: ++rpcId, method, params }),
  });
  sessionId ??= res.headers.get('mcp-session-id') ?? undefined;
  const text = await res.text();
  if (!res.ok) throw new Error(`MCP HTTP ${res.status}: ${text.slice(0, 300)}`);
  const dataLine = text.split('\n').find((l) => l.startsWith('data:'));
  const msg = JSON.parse(dataLine ? dataLine.slice(5).trim() : text);
  if (msg.error) throw new Error(`MCP error: ${JSON.stringify(msg.error)}`);
  return msg.result;
}

// Calls a tool and returns its structuredContent. Tool failures carry a JSON error with a code.
async function tool(name, args = {}) {
  const result = await rpc('tools/call', { name, arguments: args });
  if (result.isError) {
    const text = result.content?.map((c) => c.text).join(' ') ?? '';
    const code = text.match(/"code"\s*:\s*"([A-Z_]+)"/)?.[1] ?? 'UNKNOWN';
    throw new Error(`${name} failed (${code}): ${text}`);
  }
  return result.structuredContent ?? JSON.parse(result.content.find((c) => c.type === 'text' && c.text.startsWith('{'))?.text ?? '{}');
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// 1. Upload the product photo from code: announce the file, then PUT the bytes to the presigned URL.
async function uploadProductPhoto() {
  const bytes = await readFile(PRODUCT_IMAGE);
  const session = await tool('create_upload_session', {
    files: [{ content_type: 'image/png', bytes: bytes.length }],
  });
  const file = session.files?.[0] ?? session.uploads?.[0];
  if (!file?.put_url) throw new Error(`No presigned upload URL in: ${JSON.stringify(session).slice(0, 300)}`);

  const put = await fetch(file.put_url, {
    method: 'PUT',
    headers: file.headers ?? { 'Content-Type': 'image/png' },
    body: bytes,
  });
  if (!put.ok) throw new Error(`Upload failed: HTTP ${put.status} ${await put.text()}`);

  // Wait until Modelfy has taken the file in.
  for (let i = 0; i < 30; i++) {
    const got = await tool('get_uploaded_photos', { session_id: session.session_id });
    if (got.rejected?.length) throw new Error(`Photo rejected: ${JSON.stringify(got.rejected)}`);
    if (got.ready?.length) return got.ready[0].upload_id;
    if (!got.pending) break;
    await sleep(2000);
  }
  throw new Error('Uploaded photo never became ready');
}

async function main() {
  console.log('Uploading tee.png...');
  const uploadId = await uploadProductPhoto();

  console.log(`Planning ${PHOTOS} photos (${ASPECT_RATIO}, ${BACKGROUND} studio background)...`);
  const plan = await tool('plan_photos', {
    products: [{ upload_ids: [uploadId], name: PRODUCT_NAME }],
    mode: 'studio',
    background_color: BACKGROUND,
    aspect_ratio: ASPECT_RATIO,
    photos_per_product: PHOTOS,
    locale: 'en',
  });
  if (plan.enough_credits === false) throw new Error(`Not enough credits for this plan (${plan.credits} needed, ${plan.balance} available)`);
  console.log(`Price: ${plan.credits} credits.`);

  const launch = await tool('generate_photos', { quote_id: plan.quote_id });
  const session = launch.session_id ?? launch.session?.session_id;
  console.log(`Session ${session} launched. Waiting for photos...`);

  let status;
  do {
    const s = await tool('get_photo_session', { session_id: session, wait_seconds: 45 });
    status = s.status;
    if (status === 'running') console.log('  still running...');
    if (status !== 'running') {
      console.log(`Session ${status}.`);
      const photos = (s.photos ?? []).filter((p) => p.url);
      if (!photos.length) throw new Error(`No photos were made (status: ${status}).`);
      console.log('\nFinished photos:');
      for (const p of photos) console.log(p.url);
      if (s.web_url) console.log(`\nAll photos: ${s.web_url}`);
      return;
    }
  } while (true);
}

main().catch((err) => {
  console.error(`Error: ${err.message}`);
  process.exit(1);
});

