input.content:
// Turns tee.png into 4 product photos with Modelfy and prints the links.
//
// Usage (reads MODELFY_API_KEY from the environment):
//   node --env-file=.env make-photos.mjs
//   MODELFY_API_KEY=mfy_... node make-photos.mjs [path/to/product.png]

import { readFile, stat } from "node:fs/promises";
import { basename, extname } from "node:path";
import { fileURLToPath } from "node:url";

const MCP_URL = "https://hotels-gotten-trials-mozilla.trycloudflare.com/mcp";
const PHOTOS = 4;
const ASPECT_RATIO = "4:5";
const CONTENT_TYPES = { ".jpg": "image/jpeg", ".jpeg": "image/jpeg", ".png": "image/png", ".webp": "image/webp", ".heic": "image/heic" };

const apiKey = process.env.MODELFY_API_KEY;
if (!apiKey) {
  console.error("MODELFY_API_KEY is not set. Put it in .env or export it.");
  process.exit(1);
}

const imagePath = process.argv[2] ?? fileURLToPath(new URL("./tee.png", import.meta.url));
const contentType = CONTENT_TYPES[extname(imagePath).toLowerCase()];
if (!contentType) {
  console.error(`Unsupported image type: ${imagePath}`);
  process.exit(1);
}

// ---- Minimal MCP client over Streamable HTTP -------------------------------

let sessionId;
let nextId = 1;

async function rpc(method, params, { notification = false } = {}) {
  const body = notification
    ? { jsonrpc: "2.0", method, params }
    : { jsonrpc: "2.0", id: nextId++, method, params };
  const headers = {
    "content-type": "application/json",
    accept: "application/json, text/event-stream",
    authorization: `Bearer ${apiKey}`,
  };
  if (sessionId) headers["mcp-session-id"] = sessionId;

  const res = await fetch(MCP_URL, { method: "POST", headers, body: JSON.stringify(body) });
  sessionId ??= res.headers.get("mcp-session-id") ?? undefined;
  const text = await res.text();
  if (!res.ok) throw new Error(`MCP ${method} failed: HTTP ${res.status} ${text.slice(0, 300)}`);
  if (notification) return undefined;

  const isSse = (res.headers.get("content-type") ?? "").includes("text/event-stream");
  const payload = isSse
    ? text.split("\n").filter((l) => l.startsWith("data:")).map((l) => l.slice(5).trim()).join("")
    : text;
  const msg = JSON.parse(payload);
  if (msg.error) throw new Error(`MCP ${method} error: ${JSON.stringify(msg.error)}`);
  return msg.result;
}

// Calls a tool and returns its parsed JSON result. Tool errors are thrown
// with the server's error code and next_step, so the caller can act on them.
async function tool(name, args = {}) {
  const result = await rpc("tools/call", { name, arguments: args });
  const text = (result.content ?? []).map((c) => c.text ?? "").join("\n");
  let data;
  try {
    data = JSON.parse(text);
  } catch {
    data = { text };
  }
  if (result.isError) {
    const e = data?.error;
    throw new Error(`${name}: ${e?.code ?? "ERROR"}: ${e?.message ?? text}${e?.next_step ? ` (${e.next_step})` : ""}`);
  }
  return data;
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// ---- Steps -------------------------------------------------------------------

async function connect() {
  await rpc("initialize", {
    protocolVersion: "2025-06-18",
    capabilities: {},
    clientInfo: { name: "make-photos", version: "1.0.0" },
  });
  await rpc("notifications/initialized", {}, { notification: true });
}

async function uploadProductPhoto() {
  const bytes = (await stat(imagePath)).size;
  const data = await readFile(imagePath);
  const session = await tool("create_upload_session", { files: [{ content_type: contentType, bytes }] });
  console.error("create_upload_session raw:", JSON.stringify(session).slice(0, 500));

  const file = session.files?.[0];
  const putUrl = file?.put_url ?? file?.url;
  if (!putUrl) throw new Error("create_upload_session returned no upload URL");

  const putRes = await fetch(putUrl, {
    method: "PUT",
    headers: file.headers ?? { "Content-Type": contentType },
    body: data,
