async function launch(quote) {
  if (quote.enough_credits === false) {
    throw new Error(`Not enough credits: the session costs ${quote.credits}, balance ${quote.balance}`);
  }
  console.error(`Price: ${quote.credits} credits (balance ${quote.balance}). Launching ${PHOTOS} photos.`);
  return tool("generate_photos", { quote_id: quote.quote_id, user_confirmed: true });
}

async function waitForPhotos(sessionId) {
  for (;;) {
    const session = await tool("get_photo_session", { session_id: sessionId, wait_seconds: 45 });
    if (session.status !== "running") return session;
    console.error("Still running...");
  }
}

