#!/usr/bin/env node
// Turns tee.png (a linen T-shirt) into 4 product photos with Modelfy and
// prints the links to the finished photos.
//
// Usage:  MODELFY_API_KEY=mfy_... node make-photos.mjs
//         node --env-file=.env make-photos.mjs      (Node 20.6+)

import { readFile, stat } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const MCP_URL = "https://hotels-gotten-trials-mozilla.trycloudflare.com/mcp";
const IMAGE_PATH = join(dirname(fileURLToPath(import.meta.url)), "tee.png");
const PHOTO_COUNT = 4;
const MAX_POLLS = 40;

const apiKey = process.env.MODELFY_API_KEY;
if (!apiKey) {
  console.error("MODELFY_API_KEY is not set. Put it in .env or the environment.");
  process.exit(1);
}

let sessionId = null;
let nextId = 1;

// Sends one JSON-RPC request to the Modelfy MCP server and returns the
// parsed response. The server answers either with plain JSON or as an SSE stream.
async function rpc(method, params) {
  const headers = {
    Authorization: `Bearer ${apiKey}`,
    "Content-Type": "application/json",
    Accept: "application/json, text/event-stream",
    "MCP-Protocol-Version": "2025-06-18",
  };
  if (sessionId) headers["Mcp-Session-Id"] = sessionId;

  const id = nextId++;
  const res = await fetch(MCP_URL, {
    method: "POST",
    headers,
    body: JSON.stringify({ jsonrpc: "2.0", id, method, params }),
  });
  sessionId ??= res.headers.get("mcp-session-id");

  const text = await res.text();
  if (!res.ok) throw new Error(`HTTP ${res.status} from Modelfy: ${text.slice(0, 300)}`);

  const messages = res.headers.get("content-type")?.includes("text/event-stream")
    ? text
        .split("\n")
        .filter((line) => line.startsWith("data:"))
        .map((line) => JSON.parse(line.slice(5)))
    : [JSON.parse(text)];
  const reply = messages.find((m) => m.id === id);
  if (!reply) throw new Error(`No reply to ${method} in Modelfy response`);
  if (reply.error) throw new Error(`${method} failed: ${reply.error.message}`);
  return reply.result;
}

// Calls a Modelfy tool and returns its structured result. Tool-level errors
// come back as isError with a JSON body that has a code and next_step.
async function tool(name, args = {}) {
  const result = await rpc("tools/call", { name, arguments: args });
  if (result.isError) {
    const text = result.content?.map((c) => c.text).join(" ") ?? "";
    throw new Error(`${name}: ${text}`);
  }
  return result.structuredContent ?? JSON.parse(result.content.at(-1).text);
}

const log = (msg) => console.error(msg);

async function main() {
  await rpc("initialize", {
    protocolVersion: "2025-06-18",
    capabilities: {},
    clientInfo: { name: "make-photos", version: "1.0.0" },
  });
  // Required notification after initialize; the server answers 202 with no body.
  await fetch(MCP_URL, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${apiKey}`,
      "Content-Type": "application/json",
      Accept: "application/json, text/event-stream",
      "MCP-Protocol-Version": "2025-06-18",
      ...(sessionId ? { "Mcp-Session-Id": sessionId } : {}),
    },
    body: JSON.stringify({ jsonrpc: "2.0", method: "notifications/initialized" }),
  });

  const account = await tool("get_account");
  log(`Account: ${account.plan} plan, keyKind=${account.keyKind}, credits=${account.credits}`);

  // 1. Upload the product photo from code (presigned PUT).
  const bytes = await readFile(IMAGE_PATH);
  const { size } = await stat(IMAGE_PATH);
  const session = await tool("create_upload_session", {
    files: [{ content_type: "image/png", bytes: size }],
  });
  const upload = session.uploads[0];
  const put = await fetch(upload.put_url, {
    method: "PUT",
    headers: upload.headers,
    body: bytes,
  });
  if (!put.ok) throw new Error(`Upload of tee.png failed: HTTP ${put.status}`);

  let ready = [];
  for (let i = 0; i < MAX_POLLS && ready.length === 0; i++) {
    const got = await tool("get_uploaded_photos", { session_id: session.session_id });
    if (got.rejected?.length) {
      throw new Error(`Modelfy rejected tee.png: ${got.rejected[0].reason ?? JSON.stringify(got.rejected[0])}`);
    }
    ready = got.ready_upload_ids ?? [];
    if (ready.length === 0) await new Promise((r) => setTimeout(r, 2000));
  }
  if (ready.length === 0) throw new Error("tee.png did not become ready in time");
  log(`Uploaded tee.png (${ready[0]})`);

  // 2. Plan: a studio shot on a light grey background, 4:5, four photos.
  // Planning spends nothing and returns the exact price.
  const plan = await tool("plan_photos", {
    products: [{ upload_ids: [ready[0]], name: "Linen T-shirt" }],
    mode: "studio",
    background_color: "light grey",
    aspect_ratio: "4:5",
    photos_per_product: PHOTO_COUNT,
    direction: "clean product photo, soft even light, fabric texture visible",
    locale: "en",
  });
  log(`Plan: ${plan.photos} photos for ${plan.credits} credits (balance ${plan.balance})`);
  if (!plan.enough_credits) throw new Error("Not enough credits for this session");

  // 3. Launch. The script is the person's go-ahead; the price was printed above.
  const launched = await tool("generate_photos", {
    quote_id: plan.quote_id,
    user_confirmed: true,
  });
  log(`Session ${launched.session_id} started`);

  // 4. Wait until the session finishes.
  let photoSession = launched;
  for (let i = 0; i < MAX_POLLS && photoSession.status === "running"; i++) {
    photoSession = await tool("get_photo_session", {
      session_id: launched.session_id,
      wait_seconds: 45,
    });
    log(`  ${photoSession.done}/${photoSession.total} photos ready`);
  }
  if (photoSession.status === "running") {
    throw new Error(`Session ${launched.session_id} is still running; check it later with get_photo_session`);
  }

  // 5. Print the links.
  const links = (photoSession.photos ?? []).map((p) => p.url);
  if (links.length === 0) {
    throw new Error(`Session ${launched.session_id} finished with status "${photoSession.status}" and no photos`);
  }
  log(`Status: ${photoSession.status}; credits charged ${photoSession.credits.charged}, refunded ${photoSession.credits.refunded}`);
  log(`All photos: ${photoSession.web_url}`);
  for (const url of links) console.log(url);
}

main().catch((err) => {
  console.error(`Error: ${err.message}`);
  process.exit(1);
});

