#!/usr/bin/env node
// Turns tee.png (a linen T-shirt) into 4 product photos with Modelfy
// and prints the links to the finished photos.
//
// Run:  node --env-file=.env make-photos.mjs
// Needs MODELFY_API_KEY in the environment (the .env file holds it).

import { readFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const MCP_URL = 'https://hotels-gotten-trials-mozilla.trycloudflare.com/mcp';
const IMAGE_PATH = join(dirname(fileURLToPath(import.meta.url)), 'tee.png');
const PHOTO_COUNT = 4;
const ASPECT_RATIO = '4:5';
const POLL_LIMIT = 40;

const KEY = process.env.MODELFY_API_KEY;
if (!KEY) {
  console.error('MODELFY_API_KEY is not set. Put it in .env and run: node --env-file=.env make-photos.mjs');
  process.exit(1);
}

// ---- Minimal MCP client over Streamable HTTP --------------------------------

let rpcId = 0;
let sessionId = null;

async function rpc(method, params) {
  const headers = {
    Authorization: `Bearer ${KEY}`,
    'Content-Type': 'application/json',
    Accept: 'application/json, text/event-stream',
    'MCP-Protocol-Version': '2025-06-18',
  };
  if (sessionId) headers['Mcp-Session-Id'] = sessionId;

  const res = await fetch(MCP_URL, {
    method: 'POST',
    headers,
    body: JSON.stringify({ jsonrpc: '2.0', id: ++rpcId, method, params }),
  });
  const sid = res.headers.get('mcp-session-id');
  if (sid) sessionId = sid;

  const text = await res.text();
  if (!res.ok) throw new Error(`MCP ${method} failed: HTTP ${res.status} ${text.slice(0, 300)}`);

  // The server answers either plain JSON or an SSE stream with one message.
  const dataLine = text.split('\n').find((l) => l.startsWith('data: '));
  const msg = JSON.parse(dataLine ? dataLine.slice(6) : text);
  if (msg.error) throw new Error(`MCP ${method} error: ${msg.error.message}`);
  return msg.result;
}

async function callTool(name, args = {}) {
  const result = await rpc('tools/call', { name, arguments: args });
  const data = result.structuredContent ?? parseTextJson(result);
  if (result.isError) {
    const detail = JSON.stringify(data ?? result.content ?? {}).slice(0, 500);
    throw new Error(`${name} failed: ${detail}`);
  }
  return data;
}

function parseTextJson(result) {
  for (const part of result.content ?? []) {
    if (part.type !== 'text') continue;
    try {
      return JSON.parse(part.text);
    } catch {
      // not JSON, keep looking
    }
  }
  return null;
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// ---- Steps ------------------------------------------------------------------

async function uploadProductPhoto() {
  const bytes = await readFile(IMAGE_PATH);
  const session = await callTool('create_upload_session', {
    files: [{ content_type: 'image/png', bytes: bytes.length }],
  });
  const upload = session.uploads[0];

  const put = await fetch(upload.put_url, {
    method: 'PUT',
    headers: upload.headers,
    body: bytes,
  });
  if (!put.ok) throw new Error(`Upload of tee.png failed: HTTP ${put.status}`);

  // Wait until Modelfy has accepted the file.
  for (let i = 0; i < POLL_LIMIT; i++) {
    const state = await callTool('get_uploaded_photos', { session_id: session.session_id });
    const ready = (state.ready ?? state.photos ?? []).find((p) => p.upload_id === upload.upload_id);
    if (ready) return upload.upload_id;
    const rejected = (state.rejected ?? []).find((p) => p.upload_id === upload.upload_id);
    if (rejected) throw new Error(`Modelfy rejected tee.png: ${rejected.reason ?? JSON.stringify(rejected)}`);
    await sleep(1500);
  }
  throw new Error('Timed out waiting for Modelfy to accept tee.png');
}

async function planSession(uploadId) {
  return callTool('plan_photos', {
    products: [{ upload_ids: [uploadId], name: 'Linen T-shirt' }],
    mode: 'studio',
    background_color: 'white',
    model_ids: [],
    aspect_ratio: ASPECT_RATIO,
    photos_per_product: PHOTO_COUNT,
    direction: 'clean product photos, soft even light, the shirt shown as it is',
    locale: 'en',
  });
}

async function waitForPhotos(sessionId) {
  for (let i = 0; i < POLL_LIMIT; i++) {
    const session = await callTool('get_photo_session', { session_id: sessionId, wait_seconds: 45 });
    if (session.status !== 'running') return session;
    console.error(`  still running (${session.status})...`);
  }
  throw new Error('Timed out waiting for the photo session to finish');
}

// ---- Main -------------------------------------------------------------------

await rpc('initialize', {
  protocolVersion: '2025-06-18',
  capabilities: {},
  clientInfo: { name: 'make-photos', version: '1.0.0' },
});

console.error('Uploading tee.png...');
const uploadId = await uploadProductPhoto();

console.error('Planning the session...');
const plan = await planSession(uploadId);
console.error(
  `  ${PHOTO_COUNT} photos, ${plan.credits} credits` +
    (plan.enough_credits === false ? ' (NOT ENOUGH CREDITS)' : ''),
);
if (plan.enough_credits === false) throw new Error('Not enough credits to make the photos');

console.error('Making the photos...');
// The person asked for these photos by running this script, which is the yes.
const launch = await callTool('generate_photos', { quote_id: plan.quote_id, user_confirmed: true });

const done = await waitForPhotos(launch.session_id);
console.error(`Session ${done.status}.`);

const photos = done.photos ?? [];
const links = photos.filter((p) => p.url).map((p) => p.url);
if (links.length === 0) {
  throw new Error(`No photos were made (status: ${done.status})`);
}
for (const url of links) console.log(url);

